function amortize(principal, ratePct, months, firstDue) {
  const cents = (text) => {
    const [whole, frac = ''] = text.split('.');
    const sign = whole.startsWith('-') ? -1 : 1;
    return sign * (Math.abs(Number(whole)) * 100 + Number((frac + '00').slice(0, 2)));
  };
  const money = (c) => (c < 0 ? '-' : '') + Math.floor(Math.abs(c) / 100) + '.' + String(Math.abs(c) % 100).padStart(2, '0');
  const round = (x) => Math.sign(x) * Math.round(Math.abs(x));
  const r = Number(ratePct) / 1200;
  let growth = 1;
  for (let i = 0; i < months; i++) growth *= 1 + r;
  let balance = cents(principal);
  const payment = r === 0 ? Math.ceil(balance / months) : round((balance * r * growth) / (growth - 1));
  const [y0, m0, d0] = firstDue.split('-').map(Number);
  const rows = [];
  for (let n = 1; n <= months; n++) {
    const m = m0 - 1 + (n - 1);
    const y = y0 + Math.floor(m / 12);
    const month = (m % 12) + 1;
    const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
    const last = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
    const due = String(y).padStart(4, '0') + '-' + String(month).padStart(2, '0') + '-' + String(Math.min(d0, last)).padStart(2, '0');
    const interest = round(balance * r);
    const toPrincipal = n === months ? balance : Math.min(payment - interest, balance);
    balance -= toPrincipal;
    rows.push({ due, payment: money(toPrincipal + interest), interest: money(interest), principal: money(toPrincipal), balance: money(balance) });
  }
  return rows;
}
